  ('adulterate', '/əˈdʌl.tə.reɪt/', '掺杂；掺假', 'To make something impure by adding inferior substances.'),
  ('lout', '/laʊt/', '粗鲁的人；莽汉', 'A rude, clumsy man who behaves badly in public.'),
  ('caldron', '/ˈkɔːldrən/', '大锅；坩埚', 'A very large pot used for boiling liquid over a fire.'),
  ('dolt', '/doʊlt/', '笨蛋；傻瓜', 'A slow-witted person who fails to understand simple things.'),
  ('boor', '/bʊr/', '粗野的人；无礼之徒', 'A person with rough manners who ignores how others feel.')
    ) AS v(headword, ipa, def_zh, def_en)
    JOIN vocab_words w ON lower(w.headword) = v.headword
    JOIN vocab_examples e ON e.word_id = w.id
   WHERE e.scene IS NULL
      OR e.scene NOT IN ('academic', 'news', 'daily_life', 'work', 'science_tech', 'health', 'environment', 'education', 'travel', 'culture');

  RAISE NOTICE '本批 694 词:缺释义 %,例句数不等于3 %,scene 非法 %',
    n_missing, n_badcount, n_badscene;

  IF n_missing > 0 OR n_badcount > 0 OR n_badscene > 0 THEN
    RAISE EXCEPTION '断言不过:缺释义 % · 例句数异常 % · scene 非法 % —— 已回滚,库里没有任何改动',
      n_missing, n_badcount, n_badscene;
  END IF;
END
$gate$;

COMMIT;
